const StatusesPerWorkflowSchema = z
  .strictObject({
    initialStatusId: z
      .string()
      .exactOptional()
      .openapi({ description: 'The ID of the initial status for the workflow.' }),
    statuses: z
      .array(z.string().openapi({ description: 'The status IDs associated with the workflow.' }))
      .superRefine((items, ctx) => {
        const seen = new Map()
        for (const [i, val] of items.entries()) {
          const key = JSON.stringify(val)
          if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
          else seen.set(key, i)
        }
      })
      .exactOptional()
      .openapi({ description: 'The status IDs associated with the workflow.' }),
    workflowId: z.string().exactOptional().openapi({ description: 'The ID of the workflow.' }),
  })
  .openapi({ description: 'The statuses associated with each workflow.', required: [] })
  .openapi('StatusesPerWorkflow')

