export const getRestApi3AttachmentIdExpandHumanRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/attachment/{id}/expand/human',
  tags: ['Issue attachments'],
  summary: 'Get all metadata for an expanded attachment',
  description:
    "Returns the metadata for the contents of an attachment, if it is an archive, and metadata for the attachment itself. For example, if the attachment is a ZIP archive, then information about the files in the archive is returned and metadata for the ZIP archive. Currently, only the ZIP archive format is supported.\n\nUse this operation to retrieve data that is presented to the user, as this operation returns the metadata for the attachment itself, such as the attachment's ID and name. Otherwise, use [ Get contents metadata for an expanded attachment](#api-rest-api-3-attachment-id-expand-raw-get), which only returns the metadata for the attachment's contents.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** For the issue containing the attachment:\n\n *  *Browse projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project that the issue is in.\n *  If [issue-level security](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-level security permission to view the issue.\n *  If attachments are added in private comments, the comment-level restriction will be applied.",
  operationId: 'expandAttachmentForHumans',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the attachment.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returned if the request is successful. If an empty list is returned in the response, the attachment is empty, corrupt, or not an archive.',
      content: {
        'application/json': {
          schema: AttachmentArchiveMetadataReadableSchema,
          example:
            '{"entries":[{"index":0,"label":"MG00N067.JPG","mediaType":"image/jpeg","path":"MG00N067.JPG","size":"119 kB"},{"index":1,"label":"Allegro from Duet in C Major.mp3","mediaType":"audio/mpeg","path":"Allegro from Duet in C Major.mp3","size":"1.36 MB"},{"index":2,"label":"long/path/thanks/to/.../reach/the/leaf.txt","mediaType":"text/plain","path":"long/path/thanks/to/lots/of/subdirectories/inside/making/it/quite/hard/to/reach/the/leaf.txt","size":"0.0 k"}],"id":7237823,"mediaType":"application/zip","name":"images.zip","totalEntryCount":39}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: { description: 'The user does not have the necessary permission.' },
    404: {
      description:
        'Returned if:\n\n *  the attachment is not found.\n *  attachments are disabled in the Jira settings.',
    },
    409: {
      description: 'Returned if the attachment is an archive, but not a supported archive format.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

export const getRestApi3AttachmentIdExpandRawRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/attachment/{id}/expand/raw',
  tags: ['Issue attachments'],
  summary: 'Get contents metadata for an expanded attachment',
  description:
    "Returns the metadata for the contents of an attachment, if it is an archive. For example, if the attachment is a ZIP archive, then information about the files in the archive is returned. Currently, only the ZIP archive format is supported.\n\nUse this operation if you are processing the data without presenting it to the user, as this operation only returns the metadata for the contents of the attachment. Otherwise, to retrieve data to present to the user, use [ Get all metadata for an expanded attachment](#api-rest-api-3-attachment-id-expand-human-get) which also returns the metadata for the attachment itself, such as the attachment's ID and name.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** For the issue containing the attachment:\n\n *  *Browse projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project that the issue is in.\n *  If [issue-level security](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-level security permission to view the issue.\n *  If attachments are added in private comments, the comment-level restriction will be applied.",
  operationId: 'expandAttachmentForMachines',
  request: {
    params: z.object({
      id: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the attachment.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'Returned if the request is successful. If an empty list is returned in the response, the attachment is empty, corrupt, or not an archive.',
      content: {
        'application/json': {
          schema: AttachmentArchiveImplSchema,
          example:
            '{"entries":[{"entryIndex":0,"mediaType":"audio/mpeg","name":"Allegro from Duet in C Major.mp3","size":1430174},{"entryIndex":1,"mediaType":"text/rtf","name":"lrm.rtf","size":331}],"totalEntryCount":24}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: { description: 'The user does not have the necessary permission.' },
    404: {
      description:
        'Returned if:\n\n *  the attachment is not found.\n *  attachments are disabled in the Jira settings.',
    },
    409: {
      description: 'Returned if the attachment is an archive, but not a supported archive format.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

export const getRestApi3AuditingRecordRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/auditing/record',
  tags: ['Audit records'],
  summary: 'Get audit records',
  description:
    'Returns a list of audit records. The list can be filtered to include items:\n\n *  where each item in `filter` has at least one match in any of these fields:\n    \n     *  `summary`\n     *  `category`\n     *  `eventSource`\n     *  `objectItem.name` If the object is a user, account ID is available to filter.\n     *  `objectItem.parentName`\n     *  `objectItem.typeName`\n     *  `changedValues.changedFrom`\n     *  `changedValues.changedTo`\n     *  `remoteAddress`\n    \n    For example, if `filter` contains *man ed*, an audit record containing `summary": "User added to group"` and `"category": "group management"` is returned.\n *  created on or after a date and time.\n *  created or or before a date and time.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getAuditRecords',
  request: {
    query: z.object({
      offset: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(0)
        .exactOptional()
        .openapi({
          param: {
            description: 'The number of records to skip before returning the first result.',
            in: 'query',
            name: 'offset',
            schema: { default: 0, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      limit: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(1000)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of results to return.',
            in: 'query',
            name: 'limit',
            schema: { default: 1000, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      filter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The strings to match with audit field content, space separated.',
            in: 'query',
            name: 'filter',
            schema: { type: 'string' },
            required: false,
          },
        }),
      from: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The date and time on or after which returned audit records must have been created. If `to` is provided `from` must be before `to` or no audit records are returned.',
            in: 'query',
            name: 'from',
            schema: { type: 'string' },
            required: false,
          },
        }),
      to: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'The date and time on or before which returned audit results must have been created. If `from` is provided `to` must be after `from` or no audit records are returned.',
            in: 'query',
            name: 'to',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: AuditRecordsSchema,
          example:
            '{"limit":1000,"offset":0,"records":[{"associatedItems":[{"id":"jira-software-users","name":"jira-software-users","parentId":"1","parentName":"Jira Internal Directory","typeName":"GROUP"}],"authorAccountId":"5ab8f18d741e9c2c7e9d4538","authorKey":"administrator","category":"user management","changedValues":[{"changedFrom":"user@atlassian.com","changedTo":"newuser@atlassian.com","fieldName":"email"}],"created":"2014-03-19T18:45:42.967+0000","description":"Optional description","eventSource":"Jira Connect Plugin","id":1,"objectItem":{"id":"user","name":"user","parentId":"1","parentName":"Jira Internal Directory","typeName":"USER"},"remoteAddress":"192.168.1.1","summary":"User created"}],"total":1}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
    403: {
      description:
        'Returned if:\n\n *  the user does not have the required permissions.\n *  all Jira products are on free plans. Audit logs are available when at least one Jira product is on a paid plan.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

