export const postRestApi3BulkIssuesMoveRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/bulk/issues/move',
  tags: ['Issue bulk operations'],
  summary: 'Bulk move issues',
  description:
    "Use this API to submit a bulk issue move request. You can move multiple issues from multiple projects in a single request, but they must all be moved to a single project, issue type, and parent. You can't move more than 1000 issues (including subtasks) at once.\n\n#### Scenarios: ####\n\nThis is an early version of the API and it doesn't have full feature parity with the Bulk Move UI experience.\n\n *  Moving issue of type A to issue of type B in the same project or a different project: `SUPPORTED`\n *  Moving multiple issues of type A in one or more projects to multiple issues of type B in one of the source projects or a different project: `SUPPORTED`\n *  Moving issues of multiple issue types in one or more projects to issues of a single issue type in one of the source project or a different project: **`SUPPORTED`**  \n    E.g. Moving issues of story and task issue types in project 1 and project 2 to issues of task issue type in project 3\n *  Moving a standard parent issue of type A with its multiple subtask issue types in one project to standard issue of type B and multiple subtask issue types in the same project or a different project: `SUPPORTED`\n *  Moving standard issues with their subtasks to a parent issue in the same project or a different project without losing their relation: `SUPPORTED`\n *  Moving an epic issue with its child issues to a different project without losing their relation: `SUPPORTED`  \n    This usecase is **supported using multiple requests**. Move the epic in one request and then move the children in a separate request with target parent set to the epic issue id  \n      \n    (Alternatively, move them individually and stitch the relationship back with the Bulk Edit API)\n\n#### Limits applied to bulk issue moves: ####\n\nWhen using the bulk move, keep in mind that there are limits on the number of issues and fields you can include.\n\n *  You can move up to 1,000 issues in a single operation, including any subtasks.\n *  The total combined number of fields across all issues must not exceed 1,500,000. For example, if each issue includes 15,000 fields, then the maximum number of issues that can be moved is 100.\n\n**[Permissions](#permissions) required:**\n\n *  Global bulk change [permission](https://support.atlassian.com/jira-cloud-administration/docs/manage-global-permissions/).\n *  Move [issues permission](https://support.atlassian.com/jira-cloud-administration/docs/manage-project-permissions/) in source projects.\n *  Create [issues permission](https://support.atlassian.com/jira-cloud-administration/docs/manage-project-permissions/) in destination projects.\n *  Browse [project permission](https://support.atlassian.com/jira-cloud-administration/docs/manage-project-permissions/) in destination projects, if moving subtasks only.\n *  If [issue-level security](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-level security permission to view the issue.",
  operationId: 'submitBulkMove',
  request: {
    body: {
      content: {
        'application/json': {
          schema: IssueBulkMovePayloadSchema,
          example: {
            sendBulkNotification: true,
            targetToSourcesMapping: {
              'PROJECT-KEY,10001': {
                inferClassificationDefaults: false,
                inferFieldDefaults: false,
                inferStatusDefaults: false,
                inferSubtaskTypeDefault: true,
                issueIdsOrKeys: ['ISSUE-1'],
                targetClassification: [
                  {
                    classifications: {
                      '5bfa70f7-4af1-44f5-9e12-1ce185f15a38': [
                        'bd58e74c-c31b-41a7-ba69-9673ebd9dae9',
                        '-1',
                      ],
                    },
                  },
                ],
                targetMandatoryFields: [
                  {
                    fields: {
                      customfield_10000: {
                        retain: false,
                        type: 'raw',
                        value: ['value-1', 'value-2'],
                      },
                      description: {
                        retain: true,
                        type: 'adf',
                        value: {
                          content: [
                            {
                              content: [{ text: 'New description value', type: 'text' }],
                              type: 'paragraph',
                            },
                          ],
                          type: 'doc',
                          version: 1,
                        },
                      },
                      fixVersions: { retain: false, type: 'raw', value: ['10009'] },
                      labels: { retain: false, type: 'raw', value: ['label-1', 'label-2'] },
                    },
                  },
                ],
                targetStatus: [{ statuses: { '10001': ['10002', '10003'] } }],
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    201: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': { schema: SubmittedBulkOperationSchema, example: '{"taskId":"10641"}' },
      },
    },
    400: {
      description: 'Returned if the request is invalid.',
      content: {
        'application/json': {
          schema: BulkOperationErrorResponseSchema,
          example:
            '{"errors":[{"message":"Some of the issues in the issueIdsOrKeys are not valid"}]}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: BulkOperationErrorResponseSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['write:jira-work'] }],
})

export const getRestApi3BulkIssuesTransitionRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/bulk/issues/transition',
  tags: ['Issue bulk operations'],
  summary: 'Get available transitions',
  description:
    'Use this API to retrieve a list of transitions available for the specified issues that can be used or bulk transition operations. You can submit either single or multiple issues in the query to obtain the available transitions.\n\nThe response will provide the available transitions for issues, organized by their respective workflows. **Only the transitions that are common among the issues within that workflow and do not involve any additional field updates will be included.** For bulk transitions that require additional field updates, please utilise the Jira Cloud UI.\n\nYou can request available transitions for up to 1,000 issues in a single operation. This API uses pagination to return responses, delivering 50 workflows at a time.\n\n**[Permissions](#permissions) required:**\n\n *  Global bulk change [permission](https://support.atlassian.com/jira-cloud-administration/docs/manage-global-permissions/).\n *  Transition [issues permission](https://support.atlassian.com/jira-cloud-administration/docs/permissions-for-company-managed-projects/#Transition-issues/) in all projects that contain the selected issues.\n *  Browse [project permission](https://support.atlassian.com/jira-cloud-administration/docs/manage-project-permissions/) in all projects that contain the selected issues.\n *  If [issue-level security](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-level security permission to view the issue.',
  operationId: 'getAvailableTransitions',
  request: {
    query: z.object({
      issueIdsOrKeys: z
        .string()
        .openapi({
          param: {
            description:
              'Comma (,) separated Ids or keys of the issues to get transitions available for them.',
            in: 'query',
            name: 'issueIdsOrKeys',
            required: true,
            schema: { type: 'string' },
          },
        }),
      endingBefore: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: '(Optional)The end cursor for use in pagination.',
            in: 'query',
            name: 'endingBefore',
            schema: { type: 'string' },
            required: false,
          },
        }),
      startingAfter: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: '(Optional)The start cursor for use in pagination.',
            in: 'query',
            name: 'startingAfter',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: BulkTransitionGetAvailableTransitionsSchema,
          example:
            '{"availableTransitions":[{"isTransitionsFiltered":false,"issues":["EPIC-1","TASK-1"],"transitions":[{"to":{"statusId":10001,"statusName":"To Do"},"transitionId":11,"transitionName":"To Do"},{"to":{"statusId":10002,"statusName":"In Progress"},"transitionId":21,"transitionName":"In Progress"},{"to":{"statusId":10003,"statusName":"Done"},"transitionId":31,"transitionName":"Done"}]},{"isTransitionsFiltered":true,"issues":["BUG-1"],"transitions":[{"to":{"statusId":10004,"statusName":"To Do bug"},"transitionId":41,"transitionName":"To Do bug"},{"to":{"statusId":10005,"statusName":"Triage"},"transitionId":51,"transitionName":"Triage"}]}]}',
        },
      },
    },
    400: {
      description:
        'Returned if the request is not valid. For example, if a provided issue ID or key is invalid.',
      content: {
        'application/json': {
          schema: BulkOperationErrorResponseSchema,
          example:
            '{"errors":[{"message":"Some of the issues in the issueIdsOrKeys are not valid"}]}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: BulkOperationErrorResponseSchema } },
    },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: { 'application/json': { schema: BulkOperationErrorResponseSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

