export const getRestApi3ComponentRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/component',
  tags: ['Project components'],
  summary: 'Find components for projects',
  description:
    'Returns a [paginated](#pagination) list of all components in a project, including global (Compass) components when applicable.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** *Browse Projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project.',
  operationId: 'findComponentsForProjects',
  request: {
    query: z.object({
      projectIdsOrKeys: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'The project IDs and/or project keys (case sensitive).',
            in: 'query',
            name: 'projectIdsOrKeys',
            schema: { items: { type: 'string' }, type: 'array' },
            required: false,
          },
        }),
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 50, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      orderBy: z
        .enum(['description', '-description', '+description', 'name', '-name', '+name'])
        .exactOptional()
        .openapi({
          param: {
            description:
              '[Order](#ordering) the results by a field:\n\n *  `description` Sorts by the component description.\n *  `name` Sorts by component name.',
            in: 'query',
            name: 'orderBy',
            schema: {
              enum: ['description', '-description', '+description', 'name', '-name', '+name'],
              type: 'string',
            },
            required: false,
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Filter the results using a literal string. Components with a matching `name` or `description` are returned (case insensitive).',
            in: 'query',
            name: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBean2ComponentJsonBeanSchema,
          example:
            '{"isLast":false,"maxResults":2,"startAt":0,"total":2,"values":[{"description":"This is a component","id":"10000","name":"Component1","self":"http://www.example.com/jira/rest/api/2/component/10000"},{"ari":"ari:cloud:graph::integration-context/ecda99d9-9b42-4bf7-8b4f-ecb5fcf5868c/component/10001","description":"This is a global component","id":"10001","metadata":{"key1":"value1","key2":"value2"},"name":"Component2","self":"http://www.example.com/jira/rest/api/2/component/10001"}]}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    404: {
      description:
        'Returned if the project is not found or the user does not have permission to view it.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

