export const putRestApi3ConfigFieldschemesFieldsRoute = createRoute({
  method: 'put',
  path: '/rest/api/3/config/fieldschemes/fields',
  tags: ['Field schemes'],
  summary: 'Update fields associated with field schemes',
  description:
    'Update fields associated with field association schemes.\n\n**Request body limits:** a single request can update associations for at most **100 fields** (the top-level field ID keys of the request body), and each field association item may reference at most 50 field schemes. Exceeding a limit returns a 400 response with an error such as "The fieldIds must contain no more than 100 items."\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'updateFieldsAssociatedWithSchemes',
  request: {
    body: {
      description:
        'The request containing the schemes and work types to associate each field with.',
      content: {
        'application/json': {
          schema: z.record(z.string(), z.array(UpdateFieldAssociationsRequestItemSchema)),
          example: {
            customfield_10000: [{ restrictedToWorkTypes: [1, 2], schemeIds: [10000, 10001] }],
            customfield_10001: [{ schemeIds: [10002] }],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returned if the field association update was successful.',
      content: {
        'application/json': {
          schema: FieldSchemeToFieldsResponseSchema,
          example:
            '{"results":[{"fieldId":"customfield_10000","schemeId":10000,"success":true,"workTypeIds":[1,2]},{"fieldId":"customfield_10001","schemeId":10002,"success":true,"workTypeIds":[]}]}',
        },
      },
    },
    204: {
      description:
        'The request completed successfully. No additional content will be sent in the response.',
      content: { 'application/json': { schema: z.any() } },
    },
    207: {
      description: 'Returned if the field association update was partially successful.',
      content: {
        'application/json': {
          schema: FieldSchemeToFieldsResponseSchema,
          example:
            '{"results":[{"fieldId":"customfield_10000","schemeId":10000,"success":true,"workTypeIds":[1]},{"error":"Scheme 10001 doesn\'t exist","fieldId":"customfield_10001","schemeId":10001,"success":false,"workTypeIds":[2]}]}',
        },
      },
    },
    400: {
      description:
        'Returned if the request is invalid. If request is malformed, returns a collection of errors. If request is well-formed but contains invalid scheme or field IDs, returns failure details. Also returned if the request body exceeds its limits (for example, more than 100 fields), with an error such as "The fieldIds must contain no more than 100 items."',
      content: {
        'application/json': {
          schema: FieldSchemeToFieldsResponseSchema,
          example:
            '{"results":[{"error":"Scheme 99999 doesn\'t exist","fieldId":"customfield_10000","schemeId":99999,"success":false,"workTypeIds":[]},{"error":"Scheme 10001 doesn\'t exist","fieldId":"invalid_field","schemeId":10001,"success":false,"workTypeIds":[]}]}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: z.any() } },
    },
    403: {
      description: 'Returned if the user does not have the required permissions',
      content: { 'application/json': { schema: z.any() } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

