export const getRestApi3ConfigFieldschemesIdFieldsRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/config/fieldschemes/{id}/fields',
  tags: ['Field schemes'],
  summary: 'Search field scheme fields',
  description:
    'Search for fields belonging to a given field association scheme.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'searchFieldAssociationSchemeFields',
  request: {
    query: z.object({
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description: 'The starting index of the returned fields. Base index: 0.',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32().max(100),
        )
        .default(50)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The maximum number of fields to return per page, maximum allowed value is 100.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 50, format: 'int32', maximum: 100, type: 'integer' },
            required: false,
          },
        }),
      fieldId: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()).superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The field IDs to filter by, if empty then all fields belonging to a field association scheme will be returned',
            in: 'query',
            name: 'fieldId',
            schema: { items: { type: 'string' }, type: 'array', uniqueItems: true },
            required: false,
          },
        }),
    }),
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'The scheme ID to search for child fields',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returns the matching fields, at the specified page of the results.',
      content: {
        'application/json': {
          schema: PageBean2FieldAssociationSchemeFieldSearchResultSchema,
          example:
            '{"allowedOperations":["REMOVE","CHANGE_REQUIRED","CHANGE_DESCRIPTION"],"fieldId":"customfield_10000","parameters":{"description":"text","isRequired":true,"rendererType":"atlassian-wiki-renderer"},"restrictedToWorkTypes":["1","2"],"workTypeParameters":[{"description":"text","isRequired":true,"rendererType":"jira-text-renderer","workTypeId":"1"},{"description":"textarea","isRequired":false,"rendererType":"atlassian-wiki-renderer","workTypeId":"2"}]}',
        },
      },
    },
    400: {
      description:
        'Returned if the request parameters are invalid (e.g., negative startAt, maxResults exceeding limit, duplicate fieldIds).',
      content: { 'application/json': { schema: z.any() } },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: z.any() } },
    },
    403: {
      description: 'Returned if the user does not have the required permissions.',
      content: { 'application/json': { schema: z.any() } },
    },
    404: {
      description: 'Returned if the feature flag is disabled or the scheme ID is not found.',
      content: { 'application/json': { schema: z.any() } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

