export const putRestApi3FieldFieldIdContextContextIdRoute = createRoute({
  method: 'put',
  path: '/rest/api/3/field/{fieldId}/context/{contextId}',
  tags: ['Issue custom field contexts'],
  summary: 'Update custom field context',
  description:
    'Updates a [ custom field context](https://confluence.atlassian.com/adminjiracloud/what-are-custom-field-contexts-991923859.html).\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'updateCustomFieldContext',
  request: {
    params: z.object({
      fieldId: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the custom field.',
            in: 'path',
            name: 'fieldId',
            required: true,
            schema: { type: 'string' },
          },
        }),
      contextId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'The ID of the context.',
            in: 'path',
            name: 'contextId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: CustomFieldContextUpdateDetailsSchema,
          example: {
            description: 'A context used to define the custom field options for bugs.',
            name: 'Bug fields context',
          },
        },
      },
      required: true,
    },
  },
  responses: {
    204: {
      description: 'Returned if the context is updated.',
      content: { 'application/json': { schema: z.any() } },
    },
    400: { description: 'Returned if the request is not valid.', content: {} },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: {
      description: 'Returned if the user does not have the required permissions.',
      content: {},
    },
    404: { description: 'Returned if the custom field or the context is not found.', content: {} },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

