export const putRestApi3FieldFieldIdContextContextIdIssuetypeRoute = createRoute({
  method: 'put',
  path: '/rest/api/3/field/{fieldId}/context/{contextId}/issuetype',
  tags: ['Issue custom field contexts'],
  summary: 'Add issue types to context',
  description:
    'Adds issue types to a custom field context, appending the issue types to the issue types list.\n\nA custom field context without any issue types applies to all issue types. Adding issue types replaces the any-issue-type mapping unless \\{@code isAnyIssueType\\} is true. A supplied \\{@code defaultValue\\} applies to newly added mappings. If omitted, the default value of the first existing issue type mapping is copied. Existing mappings retain their defaults.\n\nIf any of the issue types exists in the custom field context, the operation fails and no issue types are added.\n\nThis API will not allow adding issue types to the global context from April 2026. Instead, an HTTP 400 response will be returned. See [CHANGE-3019](https://developer.atlassian.com/changelog/#CHANGE-3019)\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'addIssueTypesToContext',
  request: {
    params: z.object({
      fieldId: z
        .string()
        .openapi({
          param: {
            description: 'The ID of the custom field.',
            in: 'path',
            name: 'fieldId',
            required: true,
            schema: { type: 'string' },
          },
        }),
      contextId: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'The ID of the context.',
            in: 'path',
            name: 'contextId',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: AddIssueTypesToContextSchema,
          example: { issueTypeIds: ['10001', '10005', '10006'] },
        },
      },
      required: true,
    },
  },
  responses: {
    204: {
      description: 'Returned if operation is successful.',
      content: { 'application/json': { schema: z.any() } },
    },
    400: { description: 'Returned if the request is not valid.', content: {} },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: {
      description: 'Returned if the user does not have the required permissions.',
      content: {},
    },
    404: {
      description:
        'Returned if the custom field, context, or one or more issue types are not found.',
      content: {},
    },
    409: {
      description:
        'Returned if the issue type is a sub-task, but sub-tasks are disabled in Jira settings.',
      content: {},
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

