export const getRestApi3IssueLimitAdfReportRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/issue/limit/adf/report',
  tags: ['Issues'],
  summary: 'Get issue adf limit report',
  description:
    'Returns all issues whose ADF (rich text) field data breaches the universal ADF size limit.\n\nUnlike the issue limit report, which reports issues breaching per-issue entity *count* limits, this endpoint reports issues whose ADF field *byte size* exceeds that limit. The reported ADF field types are `comment_adf`, `worklog_adf`, `customfield_adf`, `description_adf` and `environment_adf`. The reported value for each issue is the number of breaching entities for that field (always 1 for the single-value description and environment fields).\n\n**[Permissions](#permissions) required:**\n\n *  *Browse projects* [project permission](https://confluence.atlassian.com/x/yodKLg) is required for the project the issues are in. Results may be incomplete otherwise\n *  *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getIssueAdfLimitReport',
  request: {
    query: z.object({
      isReturningKeys: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Return issue keys instead of issue ids in the response.\n\nUsage: Add `?isReturningKeys=true` to the end of the path to request issue keys.',
            in: 'query',
            name: 'isReturningKeys',
            schema: { default: false, type: 'boolean' },
            'x-showInExample': 'true',
            required: false,
          },
        }),
      fieldType: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'Restrict the report to the given ADF field types. Defaults to every ADF field type.\n\nFor sites with a high issue volume, consider requesting field types individually to avoid timeouts.\n\nUsage: Add `?fieldType=comment_adf&fieldType=worklog_adf` to the end of the path to report on comments and worklogs only.',
            in: 'query',
            name: 'fieldType',
            schema: { items: { type: 'string' }, type: 'array' },
            'x-showInExample': 'true',
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: IssueLimitReportResponseBeanSchema,
          example:
            '{"entitiesBreachingLimit":{"comment_adf":{"10059":[30401]},"customfield_adf":{"10051":[20301,20302]},"description_adf":{"10058":[],"10059":[]},"environment_adf":{"10058":[]},"worklog_adf":{"10056":[40501],"10058":[40502,40503]}},"issuesBreachingLimit":{"comment_adf":{"10059":1},"customfield_adf":{"10051":2},"description_adf":{"10058":1,"10059":1},"environment_adf":{"10058":1},"worklog_adf":{"10056":1,"10058":2}},"limits":{"comment_adf":1048576,"customfield_adf":1048576,"description_adf":1048576,"environment_adf":1048576,"worklog_adf":1048576}}',
        },
      },
    },
    400: { description: 'Returned if a requested field type is not a valid ADF field type.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: { description: 'Returned if the user does not have permission to complete this request.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

