export const postRestApi3JqlMatchRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/jql/match',
  tags: ['Issue search'],
  summary: 'Check issues against JQL',
  description:
    'Checks whether one or more issues would be returned by one or more JQL queries. Up to 10 JQL queries can be specified and up to 50 issue IDs included in the request.\n\n**[Permissions](#permissions) required:** None, however, issues are only matched against JQL queries where the user has:\n\n *  *Browse projects* [project permission](https://confluence.atlassian.com/x/yodKLg) for the project that the issue is in.\n *  If [issue-level security](https://confluence.atlassian.com/x/J4lKLg) is configured, issue-level security permission to view the issue.',
  operationId: 'matchIssues',
  request: {
    body: {
      content: {
        'application/json': {
          schema: IssuesAndJQLQueriesSchema,
          example: {
            issueIds: [10001, 1000, 10042],
            jqls: [
              'project = FOO',
              'issuetype = Bug',
              'summary ~ "some text" AND project in (FOO, BAR)',
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: IssueMatchesSchema,
          example:
            '{"matches":[{"matchedIssues":[10000,10004],"errors":[]},{"matchedIssues":[100134,10025,10236],"errors":[]},{"matchedIssues":[],"errors":[]},{"matchedIssues":[],"errors":["Invalid JQL: broken = value"]}]}',
        },
      },
    },
    400: {
      description:
        'Returned if `jqls` contains more than 10 JQL queries or `issueIds` contains more than 50 issue IDs.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

export const postRestApi3JqlParseRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/jql/parse',
  tags: ['JQL'],
  summary: 'Parse JQL query',
  description:
    'Parses and validates JQL queries.\n\nValidation is performed in context of the current user.\n\nThis operation can be accessed anonymously.\n\n**[Permissions](#permissions) required:** None.',
  operationId: 'parseJqlQueries',
  request: {
    query: z.object({
      validation: z
        .enum(['strict', 'warn', 'none'])
        .default('strict')
        .openapi({
          param: {
            description:
              'How to validate the JQL query and treat the validation results. Validation options include:\n\n *  `strict` Returns all errors. If validation fails, the query structure is not returned.\n *  `warn` Returns all errors. If validation fails but the JQL query is correctly formed, the query structure is returned.\n *  `none` No validation is performed. If JQL query is correctly formed, the query structure is returned.',
            in: 'query',
            name: 'validation',
            required: true,
            schema: { default: 'strict', enum: ['strict', 'warn', 'none'], type: 'string' },
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: JqlQueriesToParseSchema,
          example: {
            queries: [
              'summary ~ test AND (labels in (urgent, blocker) OR lastCommentedBy = currentUser()) AND status CHANGED AFTER startOfMonth(-1M) ORDER BY updated DESC',
              'issue.property["spaces here"].value in ("Service requests", Incidents)',
              'invalid query',
              'summary = test',
              'summary in test',
              'project = INVALID',
              'universe = 42',
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: ParsedJqlQueriesSchema,
          example:
            '{"queries":[{"query":"summary ~ test AND (labels in (urgent, blocker) OR lastCommentedBy = currentUser()) AND status CHANGED AFTER -5d ORDER BY updated DESC","structure":{"orderBy":{"fields":[{"direction":"desc","field":{"encodedName":"updated","name":"updated"}}]},"where":{"clauses":[{"field":{"encodedName":"summary","name":"summary"},"operand":{"encodedValue":"test","value":"test"},"operator":"~"},{"clauses":[{"field":{"encodedName":"labels","name":"labels"},"operand":{"encodedOperand":"urgent, blocker)","values":[{"encodedValue":"urgent","value":"urgent"},{"encodedValue":"blocker","value":"blocker"}]},"operator":"in"},{"field":{"encodedName":"lastCommentedBy","name":"lastCommentedBy","property":[{"entity":"issue","key":"propertyKey","path":"path.in.property","type":"user"}]},"operand":{"arguments":[],"encodedOperand":"currentUser()","function":"currentUser"},"operator":"="}],"operator":"or"},{"field":{"encodedName":"status","name":"status"},"operator":"changed","predicates":[{"operand":{"arguments":["-1M"],"encodedOperand":"startOfMonth(-1M)","function":"startOfMonth"},"operator":"after"}]}],"operator":"and"}}},{"query":"issue.property[\\"spaces here\\"].value in (\\"Service requests\\", Incidents)","structure":{"where":{"field":{"encodedName":"issue.property[\\"spaces here\\"].value","name":"issue.property[spaces here].value","property":[{"entity":"issue","key":"spaces here","path":"value"}]},"operand":{"encodedOperand":"(\\"Service requests\\", Incidents)","values":[{"encodedValue":"\\"Service requests\\"","value":"Service requests"},{"encodedValue":"Incidents","value":"Incidents"}]},"operator":"in"}}},{"errors":["Error in the JQL Query: Expecting operator but got \'query\'. The valid operators are \'=\', \'!=\', \'<\', \'>\', \'<=\', \'>=\', \'~\', \'!~\', \'IN\', \'NOT IN\', \'IS\' and \'IS NOT\'. (line 1, character 9)"],"query":"invalid query"},{"errors":["The operator \'=\' is not supported by the \'summary\' field."],"query":"summary = test"},{"errors":["Operator \'in\' does not support the non-list value \'\\"test\\"\' for field \'summary\'."],"query":"summary in test"},{"query":"project = INVALID","warnings":["The value \'INVALID\' does not exist for the field \'project\'."]},{"errors":["Field \'universe\' does not exist or you do not have permission to view it."],"query":"universe = 42"}]}',
        },
      },
    },
    400: {
      description: 'Returned if the request is invalid.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
    401: { description: 'Returned if the authentication credentials are incorrect.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }, {}],
})

export const postRestApi3JqlPdcleanerRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/jql/pdcleaner',
  tags: ['JQL'],
  summary: 'Convert user identifiers to account IDs in JQL queries',
  description:
    'Converts one or more JQL queries with user identifiers (username or user key) to equivalent JQL queries with account IDs.\n\nYou may wish to use this operation if your system stores JQL queries and you want to make them GDPR-compliant. For more information about GDPR-related changes, see the [migration guide](https://developer.atlassian.com/cloud/jira/platform/deprecation-notice-user-privacy-api-migration-guide/).\n\n**[Permissions](#permissions) required:** Permission to access Jira.',
  operationId: 'migrateQueries',
  request: {
    body: {
      content: {
        'application/json': {
          schema: JQLPersonalDataMigrationRequestSchema,
          example: {
            queryStrings: [
              'assignee = mia',
              'issuetype = Bug AND assignee in (mia) AND reporter in (alana) order by lastViewed DESC',
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description:
        'Returned if the request is successful. Note that the JQL queries are returned in the same order that they were passed.',
      content: {
        'application/json': {
          schema: ConvertedJQLQueriesSchema,
          example:
            '{"queriesWithUnknownUsers":[{"convertedQuery":"assignee = unknown","originalQuery":"assignee = mia"}],"queryStrings":["issuetype = Bug AND assignee in (abcde-12345) AND reporter in (abc551-c4e99) order by lastViewed DESC"]}',
        },
      },
    },
    400: {
      description:
        'Returned if at least one of the queries cannot be converted. For example, the JQL has invalid operators or invalid keywords, or the users in the query cannot be found.',
      content: { 'application/json': { schema: z.string() } },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: z.string() } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-user'] }],
})

export const postRestApi3JqlSanitizeRoute = createRoute({
  method: 'post',
  path: '/rest/api/3/jql/sanitize',
  tags: ['JQL'],
  summary: 'Sanitize JQL queries',
  description:
    "Sanitizes one or more JQL queries by converting readable details into IDs where a user doesn't have permission to view the entity.\n\nFor example, if the query contains the clause *project = 'Secret project'*, and a user does not have browse permission for the project \"Secret project\", the sanitized query replaces the clause with *project = 12345\"* (where 12345 is the ID of the project). If a user has the required permission, the clause is not sanitized. If the account ID is null, sanitizing is performed for an anonymous user.\n\nNote that sanitization doesn't make the queries GDPR-compliant, because it doesn't remove user identifiers (username or user key). If you need to make queries GDPR-compliant, use [Convert user identifiers to account IDs in JQL queries](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-jql/#api-rest-api-3-jql-sanitize-post).\n\nBefore sanitization each JQL query is parsed. The queries are returned in the same order that they were passed.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).",
  operationId: 'sanitiseJqlQueries',
  request: {
    body: {
      content: {
        'application/json': {
          schema: JqlQueriesToSanitizeSchema,
          example: {
            queries: [
              { query: "project = 'Sample project'" },
              { accountId: '5b10ac8d82e05b22cc7d4ef5', query: "project = 'Sample project'" },
              { accountId: 'cda2aa1395ac195d951b3387', query: "project = 'Sample project'" },
              { accountId: '5b10ac8d82e05b22cc7d4ef5', query: 'invalid query' },
            ],
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: SanitizedJqlQueriesSchema,
          example:
            '{"queries":[{"initialQuery":"project = \'Sample project\'","sanitizedQuery":"project = 12345"},{"initialQuery":"project = \'Sample project\'","sanitizedQuery":"project = \'Sample project\'","accountId":"5b10ac8d82e05b22cc7d4ef5"},{"initialQuery":"project = \'Sample project\'","sanitizedQuery":"project = 12345","accountId":"cda2aa1395ac195d951b3387"},{"initialQuery":"non-parsable query","errors":{"errorMessages":["Error in the JQL Query: Expecting operator but got \'query\'. The valid operators are \'=\', \'!=\', \'<\', \'>\', \'<=\', \'>=\', \'~\', \'!~\', \'IN\', \'NOT IN\', \'IS\' and \'IS NOT\'. (line 1, character 9)"],"errors":{}},"accountId":"5b10ac8d82e05b22cc7d4ef5"}]}',
        },
      },
    },
    400: {
      description: 'Returned if the request is invalid.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example: '{"errorMessages":["The queries has to be provided."],"errors":{}}',
        },
      },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: { 'application/json': { schema: ErrorCollectionSchema } },
    },
    403: {
      description: 'Returned if the user does not have the necessary permission.',
      content: {
        'application/json': {
          schema: ErrorCollectionSchema,
          example:
            '{"errorMessages":["You are not authorized to perform this action. Administrator privileges are required."],"errors":{}}',
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

export const getRestApi3LabelRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/label',
  tags: ['Labels'],
  summary: 'Get all labels',
  description: 'Returns a [paginated](#pagination) list of labels.',
  operationId: 'getAllLabels',
  request: {
    query: z.object({
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(1000)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 1000, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      query: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'Case-insensitive prefix used to filter labels before pagination.',
            in: 'query',
            name: 'query',
            schema: { type: 'string' },
            required: false,
          },
        }),
      scope: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'RECENT\\_PROJECTS or ALL\\_BROWSEABLE\\_PROJECTS. Omitted scope retains the unbounded search. Blank or unrecognised values use ALL\\_BROWSEABLE\\_PROJECTS.',
            in: 'query',
            name: 'scope',
            schema: { type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanStringSchema,
          example:
            '{"isLast":false,"maxResults":2,"startAt":0,"total":100,"values":["performance","security"]}',
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

