export const getRestApi3PoliciesProjectProjectIdOrKeyRulesRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/policies/project/{projectIdOrKey}/rules',
  tags: ['Policies'],
  summary: 'Get project policy rules',
  description:
    'Returns the configuration of the queried rule type IDs for a given project.\n\nUse this to check whether specific rules are active on a project, and if so, how they are configured.\n\nOnly rules that are actually active on the project are returned. Rules that are not active are omitted from the response.',
  operationId: 'getProjectRules',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'project ID or project key',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      ruleTypeIds: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(z.string()).superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          }),
        )
        .exactOptional()
        .openapi({
          param: {
            description: 'the set of rule type IDs to query',
            in: 'query',
            name: 'ruleTypeIds',
            schema: { items: { type: 'string' }, type: 'array', uniqueItems: true },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: '200 response',
      content: { 'application/json': { schema: z.array(StatePolicyRuleSchema) } },
    },
    401: {
      description: '401 response',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    403: {
      description: '403 response',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
    404: {
      description: '404 response',
      content: { 'application/json': { schema: ErrorResponseSchema } },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-project'] }],
})

