export const deleteRestApi3ProjectProjectIdOrKeyRoute = createRoute({
  method: 'delete',
  path: '/rest/api/3/project/{projectIdOrKey}',
  tags: ['Projects'],
  summary: 'Delete project',
  description:
    "Deletes a project.\n\nYou can't delete a project if it's archived. To delete an archived project, restore the project and then delete it. To restore a project, use the Jira UI.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).",
  operationId: 'deleteProject',
  request: {
    params: z.object({
      projectIdOrKey: z
        .string()
        .openapi({
          param: {
            description: 'The project ID or project key (case sensitive).',
            in: 'path',
            name: 'projectIdOrKey',
            required: true,
            schema: { example: '10001', type: 'string' },
          },
          example: '10001',
        }),
    }),
    query: z.object({
      enableUndo: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Whether this project is placed in the Jira recycle bin where it will be available for restoration.',
            in: 'query',
            name: 'enableUndo',
            schema: { default: true, type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    204: { description: 'Returned if the project is deleted.' },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    404: {
      description:
        'Returned if the project is not found or the user does not have permission to delete it.',
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }, {}],
})

