export const getRestApi3ProjectCategoryIdRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/projectCategory/{id}',
  tags: ['Project categories'],
  summary: 'Get project category by ID',
  description:
    'Returns a project category.\n\n**[Permissions](#permissions) required:** Permission to access Jira.',
  operationId: 'getProjectCategoryById',
  request: {
    params: z.object({
      id: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .openapi({
          param: {
            description: 'The ID of the project category.',
            in: 'path',
            name: 'id',
            required: true,
            schema: { format: 'int64', type: 'integer' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: ProjectCategorySchema,
          example:
            '{"description":"First Project Category","id":"10000","name":"FIRST","self":"https://your-domain.atlassian.net/rest/api/3/projectCategory/10000"}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    404: { description: 'Returned if the project category is not found.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['read:jira-work'] }],
})

