export const getRestApi3ScreensRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/screens',
  tags: ['Screens'],
  summary: 'Get screens',
  description:
    'Returns a [paginated](#pagination) list of all screens or those specified by one or more screen IDs.\n\n**[Permissions](#permissions) required:** *Administer Jira* [global permission](https://confluence.atlassian.com/x/x4dKLg).',
  operationId: 'getScreens',
  request: {
    query: z.object({
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(100)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 100, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      id: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(
              z
                .preprocess((val) => {
                  if (
                    typeof val !== 'string' ||
                    !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val)
                  )
                    return val
                  if (/^-?\d+$/.test(val)) return BigInt(val)
                  const num = Number(val)
                  return Number.isSafeInteger(num) ? BigInt(num) : val
                }, z.int64())
                .openapi({ type: 'integer', format: 'int64' }),
            )
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The list of screen IDs. To include multiple IDs, provide an ampersand-separated list. For example, `id=10000&id=10001`.',
            in: 'query',
            name: 'id',
            schema: {
              items: { format: 'int64', type: 'integer' },
              type: 'array',
              uniqueItems: true,
            },
            required: false,
          },
        }),
      queryString: z
        .string()
        .default('')
        .exactOptional()
        .openapi({
          param: {
            description:
              'String used to perform a case-insensitive partial match with screen name.',
            in: 'query',
            name: 'queryString',
            schema: { default: '', type: 'string' },
            required: false,
          },
        }),
      scope: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z
            .array(z.enum(['GLOBAL', 'TEMPLATE', 'PROJECT']).openapi({ default: '' }))
            .superRefine((items, ctx) => {
              const seen = new Map()
              for (const [i, val] of items.entries()) {
                const key = JSON.stringify(val)
                if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
                else seen.set(key, i)
              }
            }),
        )
        .exactOptional()
        .openapi({
          param: {
            description:
              'The scope filter string. To filter by multiple scope, provide an ampersand-separated list. For example, `scope=GLOBAL&scope=PROJECT`.',
            in: 'query',
            name: 'scope',
            schema: {
              items: { default: '', enum: ['GLOBAL', 'TEMPLATE', 'PROJECT'], type: 'string' },
              type: 'array',
              uniqueItems: true,
            },
            required: false,
          },
        }),
      orderBy: z
        .enum(['name', '-name', '+name', 'id', '-id', '+id'])
        .exactOptional()
        .openapi({
          param: {
            description:
              '[Order](#ordering) the results by a field:\n\n *  `id` Sorts by screen ID.\n *  `name` Sorts by screen name.',
            in: 'query',
            name: 'orderBy',
            schema: { enum: ['name', '-name', '+name', 'id', '-id', '+id'], type: 'string' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageBeanScreenSchema,
          example:
            '{"isLast":true,"maxResults":100,"self":"https://your-domain.atlassian.net/rest/api/3/screens","startAt":0,"total":3,"values":[{"id":1,"name":"Default Screen","description":"Provides for the update all system fields."},{"id":2,"name":"Workflow Screen","description":"This screen is used in the workflow and enables you to assign issues."},{"id":3,"name":"Resolve Issue Screen","description":"Offers the ability to set resolution, change fix versions, and assign an issue."}]}',
        },
      },
    },
    401: { description: 'Returned if the authentication credentials are incorrect or missing.' },
    403: { description: 'Returned if the user does not have the necessary permission.' },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-project'] }],
})

