export const getRestApi3StatusesSearchRoute = createRoute({
  method: 'get',
  path: '/rest/api/3/statuses/search',
  tags: ['Status'],
  summary: 'Search statuses paginated',
  description:
    'Returns a [paginated](https://developer.atlassian.com/cloud/jira/platform/rest/v3/intro/#pagination) list of statuses that match a search on name or project.\n\n**[Permissions](#permissions) required:**\n\n *  *Administer projects* [project permission.](https://confluence.atlassian.com/x/yodKLg)\n *  *Administer Jira* [project permission.](https://confluence.atlassian.com/x/yodKLg)',
  operationId: 'search',
  request: {
    query: z.object({
      projectId: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description: 'The project the status is part of or null for global statuses.',
            in: 'query',
            name: 'projectId',
            schema: { type: 'string' },
            required: false,
          },
        }),
      startAt: z
        .preprocess((val) => {
          if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
            return val
          if (/^-?\d+$/.test(val)) return BigInt(val)
          const num = Number(val)
          return Number.isSafeInteger(num) ? BigInt(num) : val
        }, z.int64())
        .default(0n)
        .exactOptional()
        .openapi({
          param: {
            description:
              'The index of the first item to return in a page of results (page offset).',
            in: 'query',
            name: 'startAt',
            schema: { default: 0, format: 'int64', type: 'integer' },
            required: false,
          },
        }),
      maxResults: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int32(),
        )
        .default(200)
        .exactOptional()
        .openapi({
          param: {
            description: 'The maximum number of items to return per page.',
            in: 'query',
            name: 'maxResults',
            schema: { default: 200, format: 'int32', type: 'integer' },
            required: false,
          },
        }),
      searchString: z
        .string()
        .max(255)
        .exactOptional()
        .openapi({
          param: {
            description:
              'Term to match status names against or null to search for all statuses in the search scope.',
            in: 'query',
            name: 'searchString',
            schema: { maxLength: 255, type: 'string' },
            required: false,
          },
        }),
      statusCategory: z
        .string()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Category of the status to filter by. The supported values are: `TODO`, `IN_PROGRESS`, and `DONE`.',
            in: 'query',
            name: 'statusCategory',
            schema: { type: 'string' },
            required: false,
          },
        }),
      includeGlobalStatuses: z
        .stringbool()
        .exactOptional()
        .openapi({
          param: {
            description:
              'Whether to include global statuses (scope = null, not tied to any project) in the response. Defaults to false. Only relevant for project scoped queries.',
            in: 'query',
            name: 'includeGlobalStatuses',
            schema: { type: 'boolean' },
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful.',
      content: {
        'application/json': {
          schema: PageOfStatusesSchema,
          example:
            '{"isLast":true,"maxResults":2,"nextPage":"https://your-domain.atlassian.net/rest/api/3/statuses/search?startAt=2&maxResults=2","self":"https://your-domain.atlassian.net/rest/api/3/statuses/search?startAt=0&maxResults=2","startAt":0,"total":5,"values":[{"description":"The issue is resolved","id":"1000","name":"Finished","scope":{"project":{"id":"1"},"type":"PROJECT"},"statusCategory":"DONE"}]}',
        },
      },
    },
    400: { description: 'Returned if the request is not valid.' },
    401: {
      description:
        "Returned if the authentication credentials are incorrect or missing, or the caller doesn't have permissions to perform the operation.",
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: ['manage:jira-configuration'] }],
})

