export const getRestAtlassianConnect1MigrationConnectKeyJiraIssueFieldsKeyTaskRoute = createRoute({
  method: 'get',
  path: '/rest/atlassian-connect/1/migration/{connectKey}/{jiraIssueFieldsKey}/task',
  tags: ['Migration of Connect modules to Forge'],
  summary: 'Get Connect issue field migration task',
  description:
    "Returns the details of a Connect issue field's migration to Forge.\n\nWhen migrating a Connect app to Forge, [Issue Field](https://developer.atlassian.com/cloud/jira/software/modules/issue-field/) modules\nmust be converted to [Custom field](https://developer.atlassian.com/platform/forge/manifest-reference/modules/jira-custom-field/). When the\nForge version of the app is installed, Forge creates a\n[background task](https://developer.atlassian.com/cloud/jira/platform/rest/v3/api-group-tasks/#api-group-tasks) to track the\nmigration of field data across. This endpoint returns the status and other details of that background task.\n\nFor more details, see\n[Jira modules > Jira Custom Fields](https://developer.atlassian.com/platform/adopting-forge-from-connect/migrate-jira-custom-fields/).\n\n**[Permissions](#permissions) required:** Only Connect and Forge apps can make this request.",
  operationId: 'ConnectToForgeMigrationFetchTaskResource.fetchMigrationTask_get',
  request: {
    params: z.object({
      connectKey: z
        .string()
        .openapi({
          param: {
            description:
              'The key of the Connect app that contains the Jira issue field being migrated.',
            example: 'com.example.app',
            in: 'path',
            name: 'connectKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
      jiraIssueFieldsKey: z
        .string()
        .openapi({
          param: {
            description: 'The module key of the Connect issue field being migrated.',
            example: 'my-custom-field',
            in: 'path',
            name: 'jiraIssueFieldsKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Returned if the request is successful and a migration task is found.',
      content: { 'application/json': { schema: TaskProgressSchema } },
    },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: {
        'application/json': {
          schema: OperationMessageSchema,
          example: {
            message: 'Access to this resource must be authenticated as an app.',
            statusCode: 401,
          },
        },
      },
    },
    404: {
      description:
        'Returned if:\n* no migrated Forge module with the given key is found.\n* no ongoing migration task exists for the custom field.',
      content: {
        'application/json': {
          schema: OperationMessageSchema,
          example: { message: 'No ongoing migration task for the custom field.', statusCode: 404 },
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: [] }],
})

export const postRestAtlassianConnect1MigrationConnectKeyJiraIssueFieldsKeyTaskRoute = createRoute({
  method: 'post',
  path: '/rest/atlassian-connect/1/migration/{connectKey}/{jiraIssueFieldsKey}/task',
  tags: ['Migration of Connect modules to Forge'],
  summary: 'Submit Connect issue field migration task',
  description:
    'Submits a request to trigger migration of connect issue field to its Forge custom field counterpart.\n\nWhen migrating a Connect app to Forge, [Issue Field](https://developer.atlassian.com/cloud/jira/software/modules/issue-field/) modules\nmust be converted to [Custom field](https://developer.atlassian.com/platform/forge/manifest-reference/modules/jira-custom-field/) modules.\nThis endpoint triggers the background migration of field data. Use the GET endpoint to retrieve\nthe status and progress of the task.\n\nFor more details, see\n[Jira modules > Jira Custom Fields](https://developer.atlassian.com/platform/adopting-forge-from-connect/migrate-jira-custom-fields/).\n\n**[Permissions](#permissions) required:** Only Connect and Forge apps can make this request.',
  operationId: 'ConnectToForgeMigrationTaskSubmissionResource.submitTask_post',
  request: {
    params: z.object({
      connectKey: z
        .string()
        .openapi({
          param: {
            description:
              'The key of the Connect app that contains the Jira issue field being migrated.',
            example: 'com.example.app',
            in: 'path',
            name: 'connectKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
      jiraIssueFieldsKey: z
        .string()
        .openapi({
          param: {
            description: 'The module key of the Connect issue field being migrated.',
            example: 'my-custom-field',
            in: 'path',
            name: 'jiraIssueFieldsKey',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      retriggerCompletedMigration: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            description: 'Whether to retrigger the migration if it has already completed.',
            explode: true,
            in: 'query',
            name: 'retriggerCompletedMigration',
            required: false,
            schema: { default: false, type: 'boolean' },
            style: 'form',
          },
        }),
    }),
  },
  responses: {
    202: { description: 'Returned if the migration task was submitted successfully.' },
    401: {
      description: 'Returned if the authentication credentials are incorrect or missing.',
      content: {
        'application/json': {
          schema: OperationMessageSchema,
          example: {
            message: 'Access to this resource must be authenticated as an app.',
            statusCode: 401,
          },
        },
      },
    },
    404: {
      description: 'Returned if no migrated Forge module with the given key is found.',
      content: {
        'application/json': {
          schema: OperationMessageSchema,
          example: {
            message: 'No migrated Forge module with given key is found.',
            statusCode: 404,
          },
        },
      },
    },
    409: {
      description: 'Returned if a migration task is already in progress for the field.',
      content: {
        'application/json': {
          schema: OperationMessageSchema,
          example: {
            message:
              'Failed to trigger migration task because of already in progress task for the field.',
            statusCode: 409,
          },
        },
      },
    },
  },
  security: [{ basicAuth: [] }, { OAuth2: [] }],
})

